clean () { for t in "$@"; do find $FH/default_repository/caches -name "*$t*" ! -name '*.jar' -exec rm -rf {} + 2>/dev/null; find $FH/default_repository/caches -name "$t*.jar" -exec rm -f {} + 2>/dev/null; done; }
