  local d=$1 c=$2 th=${3:-1}
  clean $c
  echo "################ $c compiled, FORTRESS_THREADS=$th"
  (cd $d && timeout 300 $FH/bin/fortress compile $c.fss 2>&1 | filt | head -20; echo "compile exit=${PIPESTATUS[0]}")
