walkrun () {
  local d=$1 c=$2 th=${3:-1}
  echo "################ $c walk, FORTRESS_THREADS=$th"
  (cd $d && FORTRESS_THREADS=$th timeout 300 $FH/bin/fortress $c.fss 2>&1 | filt | head -30; echo "walk exit=${PIPESTATUS[0]}")
}
EOF
echo ok

